/*******************  Hide Stats on About Page ****************************/
.about__right-side h3:nth-of-type(2),
.about__activities, .about__stats {
  display: none !important;
}
/*****************************************************************/

/**********************Hide allow PM from profile page (JP)**************************/
div.control-group.private-messages {
    display: none;
}
/***********************************/


/********************************Highlight pinned topic**********************************/
tr[data-topic-id='89225'], tr[data-topic-id='89226'], tr[data-topic-id='89227'], tr[data-topic-id='89228'], tr[data-topic-id='89229'], tr[data-topic-id='89222'], tr[data-topic-id='89231'], tr[data-topic-id='89232'], tr[data-topic-id='89557'], tr[data-topic-id='###'] {
/*tr.pinned*/
    background-color: #ccffcc!important;
}
/**************************************/

/*******************  Former Theme Component (Misc MRF Tweaks) ****************************/

///// Style the core Discourse header //////
/*.IGNOREd-header #site-logo {
    max-height: 100px;
}*/

// Chris Malone  Additions //
.d-header #site-logo {
    height:4em;
}
.d-header {
    height:6rem!important;
}

/*.IGNOREd-header {
    height: 120px;
}*/

// Add underline to link within posts upon hovering
.cooked a:hover {
    text-decoration: underline;
}


// Add vertical spacing to the list of expandable details on the FAQ page
.static-faq details {
    //padding-bottom: 10px;
    margin-bottom: 1px;
    //padding: 1px;
}


.topic-list .main-link a.title, a.mineral-services-directory {
    color: #2575AD!important;
    font-weight: bold!important;
}

.topic-list .main-link a.title:hover, a.mineral-services-directory:hover {
    color: #cd2626!important;
}


// Taylor additions ///

// Remove padding
.list-controls .container {
    padding-left: 0px;
    padding-right: 0px;
}

// Darken the category descriptions
.category-description {
   color: #646464 !important;
}


/*****************************************************************/

/*******************  Set Category Logo Max Height (JP) ****************************/

.category-logo.aspect-image {
    max-width: 200px;
    --max-height: 75px;
    margin-top: 3px;
    margin-bottom: 3px;
    margin-right: 15px;
}
/*****************************************************************/

/*******************  Style Business Member Signature and Post Text Color (TH) ****************************/
.group-signature {
    font-weight: bold;
    a {
        color: #08c !important;
        &:hover {
            text-decoration: underline;
        }
    }
}
/*******Business Member Post Color*******/
.group-BusinessMember {
  color: #08c !important;
}

.topic-post.post--group-BusinessMember .cooked p a {
    color: #646464 !important;
font-weight:bold!important;
}

/*****************************************************************/

/*******************  "New Topic" and "Post Topic" Button ****************************/

button#create-topic.btn,
button.groups-header-new, 
#new-create-topic {
    color: white!important;
    background: var(--tertiary);
}

// Post Topic button on composer
.topic .btn.btn-icon-text.btn-primary.create {
    color: white!important;
    background: var(--tertiary)!important;
}
#create-topic > svg {
    fill:#fff!important;
}
/*****************************************************************/
// Hides the About Field on Profile page (and removes edit access) for non-business members (this is an upsell)
// This will also show the about field for admin users
body:not(.primary-group-businessmember):not(.admin-user) .pref-bio {
    display: none;
}

body:not(.primary-group-businessmember):not(.admin-user) .pref-website {
    display: none;
}

body:not(.primary-group-businessmember):not(.admin-user) .pref-profile-bg {
    display: none;
}

body:not(.primary-group-businessmember):not(.admin-user) .names__secondary {
    display: none;
}

/****************** Change Topic Hover Color *******************/
.topic-list-item,
.latest-topic-list-item {
  &:hover {
    background: rgba(var(--primary-rgb), 0.055)!important;
  }
}

/******** Hide Author on Published Pages **********************/
.published-page-author {
    display:none!important;
}


/************** Hide Click Badge in Post for Non-Admins *****************/
/* 1. Hide them for everyone by default */
a[data-clicks]::after {
    display: none !important;
}

/* 2. Force them back on ONLY for staff */
body.staff a[data-clicks]::after {
    display: inline-block !important;
}

/**************** PM Icon Color *******************/
.private-message-glyph {
    color:green!important;
}
.composer-action-privateMessage {
  background-color: #e0ffe2!important;
}
.composer-action-privateMessage .grippie {
  background-color: #28b332!important;
}
.private-message .d-editor-preview-wrapper {
    /* Your styles here */
    background-color: #ffffff;
    border: 1px solid #ccc;
}
.private-message .d-editor-preview {
    padding:20px!important;
}

